def dice_value(n):
    value = 3.5
    for _ in range(n - 1):
        value = sum(max(face, value) for face in range(1, 7)) / 6
    return value


def dice_threshold(n):
    if n == 1:
        return 1
    later = dice_value(n - 1)
    for face in range(1, 7):
        if face >= later:
            return face
    return 6
